package com.learnagent.workspace;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="workspace_artifacts")public class WorkspaceArtifact{@Id private UUID id;@Column(name="workspace_id",nullable=false)private UUID workspaceId;@Column(name="artifact_type",nullable=false)private String artifactType;@Column(name="relative_path",nullable=false)private String relativePath;@Column(name="source_url")private String sourceUrl;private String checksum;@Column(name="created_at",nullable=false)private Instant createdAt;protected WorkspaceArtifact(){}public WorkspaceArtifact(UUID workspace,String type,String path,String source,String checksum){id=UUID.randomUUID();workspaceId=workspace;artifactType=type;relativePath=path;sourceUrl=source;this.checksum=checksum;createdAt=Instant.now();}public UUID getId(){return id;}public String getArtifactType(){return artifactType;}public String getRelativePath(){return relativePath;}public String getSourceUrl(){return sourceUrl;}public String getChecksum(){return checksum;}public Instant getCreatedAt(){return createdAt;}}
